// LauncherCore's checks, the same as launcher/desktop/tests/core_test.cpp's: `swift test`.
import XCTest
@testable import LauncherCore

final class CoreTests: XCTestCase {
    func testParseConfig() {
        let text = """
            // generated by OpenMoHAA, do not modify
            unbindall
            bind TAB "+scores"
            seta name "Some Body"\r
            seta cg_crosshair_length "5"
            SETA CG_Crosshair_Color "#00ff00" // green
            set r_mode -1; seta r_customwidth "2560"; seta r_customheight 1440
            seta password "a;b//c"
            /* seta r_fullscreen "0" */ seta r_noborder "1"
            seta empty ""
            seta unterminated "abc
            seta spaced one two
            seta ünïcode "ä"

            """
        let c = parseConfig(text)
        XCTAssertEqual(c["name"], "Some Body")
        XCTAssertEqual(c["cg_crosshair_length"], "5")
        XCTAssertEqual(c["cg_crosshair_color"], "#00ff00")
        XCTAssertEqual(c["r_mode"], "-1")
        XCTAssertEqual(c["r_customwidth"], "2560")
        XCTAssertEqual(c["r_customheight"], "1440")
        XCTAssertEqual(c["password"], "a;b//c")
        XCTAssertNil(c["r_fullscreen"])
        XCTAssertEqual(c["r_noborder"], "1")
        XCTAssertEqual(c["empty"], "")
        XCTAssertEqual(c["unterminated"], "abc")
        XCTAssertEqual(c["spaced"], "one two")
        XCTAssertEqual(c["ünïcode"], "ä")
        XCTAssertNil(c["tab"])
    }

    func testEdits() {
        var e = CvarEdits(defaults: [("name", ""), ("cg_crosshair_length", "4"), ("r_fullscreen", "1")])
        XCTAssertEqual(e.get("cg_crosshair_length"), "4")
        XCTAssertTrue(e.changes.isEmpty)

        e.load(["name": "Player", "cg_crosshair_length": "6"])
        XCTAssertEqual(e.get("name"), "Player")
        XCTAssertEqual(e.get("cg_crosshair_length"), "6")
        XCTAssertEqual(e.get("r_fullscreen"), "1")
        XCTAssertTrue(e.changes.isEmpty)

        e.set("cg_crosshair_length", "8")
        XCTAssertTrue(e.changed("cg_crosshair_length"))
        // a change made in the game to another setting comes in; the launcher's own change stays
        e.load(["name": "Renamed", "cg_crosshair_length": "7"])
        XCTAssertEqual(e.get("name"), "Renamed")
        XCTAssertEqual(e.get("cg_crosshair_length"), "8")
        XCTAssertEqual(e.changes.map { $0.0 }, ["cg_crosshair_length"])
        XCTAssertEqual(e.changes.map { $0.1 }, ["8"])

        e.set("cg_crosshair_length", "7")
        XCTAssertTrue(e.changes.isEmpty)

        e.set("r_fullscreen", "0")
        e.applied()
        XCTAssertTrue(e.changes.isEmpty)
        e.load(["r_fullscreen": "0"])
        XCTAssertEqual(e.get("r_fullscreen"), "0")
        XCTAssertFalse(e.changed("r_fullscreen"))
    }

    func testArgs() {
        XCTAssertEqual(engineArg("plain"), "plain")
        XCTAssertEqual(engineArg("with space"), "with space")
        XCTAssertEqual(engineArg("a;b"), "\"a;b\"")
        XCTAssertEqual(engineArg("a+b"), "\"a+b\"")
        XCTAssertEqual(engineArg("http://x"), "\"http://x\"")
        XCTAssertEqual(engineArg("say \"hi\""), "say hi")
        XCTAssertEqual(engineArg(""), "\"\"")
        XCTAssertEqual(engineArg("tab\there"), "tab here")
        XCTAssertEqual(engineArg("ünïcode"), "ünïcode")

        var l = Launch()
        l.game = .spearhead
        l.cvars = [("name", "A B"), ("cg_crosshair_color", "00FF00")]
        l.password = "pw;1"
        l.rcon = "r"
        l.address = "1.2.3.4:12203"
        XCTAssertEqual(buildArgs(l), [
            "+set", "com_target_game", "1", "+set", "name", "A B", "+set", "cg_crosshair_color", "00FF00",
            "+set", "password", "\"pw;1\"", "+set", "rconPassword", "r", "+connect", "1.2.3.4:12203",
        ])
        XCTAssertEqual(buildArgs(Launch()), ["+set", "com_target_game", "0"])
    }

    func testMisc() {
        XCTAssertEqual(trimmed("  1.2.3.4:12203 \t"), "1.2.3.4:12203")
        XCTAssertTrue(sameAddress("Host.Example", "host.example:12203"))
        XCTAssertFalse(sameAddress("host:12204", "host"))
        XCTAssertEqual(parseColor("#00ff7F"), 0x00FF7F)
        XCTAssertNil(parseColor("12345"))
        XCTAssertNil(parseColor("GGGGGG"))
        XCTAssertEqual(colorHex(0x0A0B0C), "0A0B0C")

        var x = crosshairBoxes(length: 4, gap: 3, thickness: 1)
        XCTAssertEqual(x.arms[0], Box(x: -7, y: 0, w: 4, h: 1))
        XCTAssertEqual(x.arms[1].x, 4)
        XCTAssertEqual(x.arms[3].y, 4)
        XCTAssertEqual(x.extent, 15)
        x = crosshairBoxes(length: 5, gap: 3, thickness: 2)
        XCTAssertEqual(x.arms[1].x, 4)
        XCTAssertEqual(x.arms[0].x, -7)
        XCTAssertEqual(x.extent, 16)
        x = crosshairBoxes(length: 0, gap: 1000, thickness: 99)
        XCTAssertEqual(x.arms[1].w, 1)
        XCTAssertEqual(x.arms[0].h, 16)
        XCTAssertEqual(x.arms[1].x, 16 + 56)

        XCTAssertEqual(DisplayMode(fullscreen: "1", noborder: "1", borderlessWindow: "0"), .space)
        XCTAssertEqual(DisplayMode(fullscreen: "1", noborder: "0", borderlessWindow: "1"), .exclusive)
        XCTAssertEqual(DisplayMode(fullscreen: "1", noborder: "1", borderlessWindow: "1"), .borderlessFullscreen)
        XCTAssertEqual(DisplayMode(fullscreen: "0", noborder: "0", borderlessWindow: "0"), .window)
        XCTAssertEqual(DisplayMode(fullscreen: "0", noborder: "1", borderlessWindow: "0"), .borderlessWindow)
        var e = CvarEdits(defaults: [("r_fullscreen", "1"), ("r_noborder", "0"), ("r_borderlessWindow", "0")])
        DisplayMode.borderlessFullscreen.apply(to: &e)
        XCTAssertEqual(DisplayMode(fullscreen: e.get("r_fullscreen"), noborder: e.get("r_noborder"),
                                   borderlessWindow: e.get("r_borderlessWindow")), .borderlessFullscreen)
        DisplayMode.space.apply(to: &e)
        XCTAssertEqual(e.get("r_borderlessWindow"), "0")

        let list = resolutionList(displayModes: [Resolution(1920, 1080), Resolution(1280, 720), Resolution(320, 200)],
                                  desktop: Resolution(1920, 1080))
        XCTAssertEqual(list.first, Resolution(1920, 1080))
        XCTAssertEqual(list.filter { $0 == Resolution(1920, 1080) }.count, 1)
        XCTAssertFalse(list.contains(Resolution(2560, 1440)))
        XCTAssertFalse(list.contains(Resolution(320, 200)))
    }

    func testFindConfig() throws {
        let fm = FileManager.default
        let root = fm.temporaryDirectory.appendingPathComponent("mohl-core-test-\(UUID().uuidString)")
        defer { try? fm.removeItem(at: root) }
        let home = root.appendingPathComponent("home"), base = root.appendingPathComponent("base")
        func write(_ url: URL, _ text: String) throws {
            try fm.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
            try text.write(to: url, atomically: true, encoding: .utf8)
        }
        let aa = home.appendingPathComponent("main/configs/omconfig.cfg")
        try write(aa, "seta name a\n")
        try write(base.appendingPathComponent("maintt/configs/unnamedsoldier.cfg"), "seta name b\n")

        XCTAssertEqual(findConfig(homes: [home, base], game: .alliedAssault)?.path, aa.path)
        XCTAssertEqual(findConfig(homes: [home, base], game: .spearhead)?.path, aa.path)
        XCTAssertEqual(findConfig(homes: [home, base], game: .breakthrough)?.path, aa.path)
        let bt = home.appendingPathComponent("maintt/configs/omconfig.cfg")
        try write(bt, "seta name c\n")
        XCTAssertEqual(findConfig(homes: [home, base], game: .breakthrough)?.path, bt.path)
        XCTAssertNil(findConfig(homes: [root.appendingPathComponent("none")], game: .alliedAssault))
        XCTAssertEqual(readConfig(bt)?["name"], "c")
    }
}
